#!/usr/bin/env python3
"""Temporary isolated validation bootstrap; excluded from the final PR."""
import base64
import pathlib
import subprocess
import zlib

BASE = "012edc766b3c3f6d2c35ca4bc7af9d2676442709"
PATHS = ['README.md', 'docs/CONFIGURATION.md', 'docs/DVM_OPERATORS.md', 'docs/DVM_SUPPORT_MATRIX.md', 'docs/FAQ.md', 'docs/GUC_CATALOG.md', 'docs/LIMITATIONS.md', 'docs/SQL_REFERENCE.md', 'src/config/dvm.rs', 'src/dvm/operators/recursive_cte.rs', 'tests/e2e_cte_tests.rs']
PATCH = ""
for name in PATHS:
    data = subprocess.check_output(["git", "show", f"{BASE}:{name}"])
    pathlib.Path(name).write_bytes(data)
patch = zlib.decompress(base64.b64decode(PATCH))
subprocess.run(["git", "apply", "--check", "-"], input=patch, check=True)
subprocess.run(["git", "apply", "-"], input=patch, check=True)
subprocess.run(["git", "diff", "--check"], check=True)
